-- Minimal draft test bridge.
-- Package sandbox disables loadfile/dofile, so keep only the draft's
-- create_electromagnet, animation/render path, and field hook here.
-- PNG sprite registration disabled for crash isolation (CustomSprites=0).
local magnetTestX = 1000
local magnetTestY = 350
local magnetTestMagnets = {}
local magnetTestFrame = 0
local magnetSprite = 0
local magnetRingOutSprite = 0
local magnetRingInSprite = 0
local magnetSparkSprite = 0

local function magnetChat(message)
  if type(showChatMessage) == "function" then
    showChatMessage("[magnet] " .. message, 7)
  end
end

local function create_electromagnet(x, y, polarity)
  local magnet = { x = x, y = y, polarity = polarity, age = 0 }
  magnetTestMagnets[#magnetTestMagnets + 1] = magnet
  return magnet
end

-- Draft hook retained; scene-object iteration is not exposed by this package.
function do_magnetic_field(magnet, apply_force_flag, force_wake)
  return magnet ~= nil and apply_force_flag ~= nil and force_wake ~= nil
end

local function magnetFrame()
  magnetTestFrame = magnetTestFrame + 1
  for _, magnet in ipairs(magnetTestMagnets) do
    magnet.age = magnet.age + 1
    do_magnetic_field(magnet, true, false)
  end
  return 0
end

if type(registerCallback_onFrame) == "function" then
  registerCallback_onFrame(magnetFrame)
end

function onChatInput(msg)
  local command = tostring(msg or ""):lower()
  if command == "/magnet" or command == "/magnet attract" then
    create_electromagnet(magnetTestX, magnetTestY, -1)
    magnetChat(string.format("spawned at %d,%d; attract rings active",
      magnetTestX, magnetTestY))
    return 1
  end
  if command == "/magnet repel" then
    create_electromagnet(magnetTestX, magnetTestY, 1)
    magnetChat(string.format("spawned at %d,%d; repel rings active",
      magnetTestX, magnetTestY))
    return 1
  end
  if command == "/magnet clear" then
    magnetTestMagnets = {}
    magnetChat("cleared")
    return 1
  end
  return 0
end

local previousInitialize = initialize
function initialize()
  local result = previousInitialize()
  magnetChat("visual sprites disabled; /magnet logic-only test")
  return result
end

